// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title IBackingVault
/// @notice Per-basket $WIF staking ("back a basket"), weekly Beat-SPY settlement and reward accounting
///         (ARCHITECTURE.md section 5.5, ADR-0007).
/// @dev - Rewards for backers use a MasterChef-style accumulator per basket over ACTIVE stake (stake that is pending
///        unstake does not earn).
///      - The curator's own stake is a normal position (it earns as a backer). The curator ALSO receives the curator
///        share when curatorActive(basket) is true at settlement: the curator's active stake >= factory.minCuratorStake().
///      - NAV is unit-based: nav = sum(rawUnits_i * answer_i) * 1e10 / 1e18 (18-dec USD per 1e18 shares), read from
///        basket.components() and registry feeds. It ignores donations, so it can't be gamed.
///      - Epoch boundaries: EPOCH_ANCHOR + k * EPOCH_LENGTH. settle() is allowed once block.timestamp >= the first
///        boundary strictly after lastSettledAt.
///      - Settlement outcome: released only if every feed is valid AND navNow * benchLast > navLast * benchNow
///        (strictly beat). Otherwise all queued rewards are burned (sent to DEAD). In either case, re-snapshot.
///      - If released: backer queue -> accumulator (burned if totalActiveStake == 0); curator queue -> curator
///        claimable (burned if !curatorActive).
///      - A basket registered with an invalid snapshot (a stale feed) stores nav=0. The next settle then burns and re-snapshots.
///      - WARMUP (anti just-in-time staking, review finding R-1): weekend feeds are frozen, so a settle outcome is
///        predictable before it is called. New stake via stake()/stakeFor() therefore goes to `warming` and does NOT
///        earn until the basket's NEXT settle activates it. At settle, AFTER distributing the released rewards,
///        totalWarming moves to totalActive and settleCount++. Per-account activation is lazy: whenever a position is
///        touched (stake, requestUnstake, claim, views) and p.warmingSettleId < s.settleCount, warming becomes active
///        with rewardDebt based on accAtSettle[basket][p.warmingSettleId + 1] (the accumulator right after the
///        activating settle), so warmed stake earns from exactly the settle after it was added.
///        EXCEPTION: the factory's stakeFor during createBasket (same tx as registerBasket, i.e. settleCount == 0
///        and block.timestamp == lastSettledAt) is active immediately, so a new basket's curator is active in epoch 1.
///        requestUnstake may take from `warming` first, then `active`. Warming stake counts toward curatorActive: NO.
interface IBackingVault {
    struct Position {
        uint256 active; // earning stake
        uint256 warming; // added since the last settle, not earning yet (activates at the next settle)
        uint64 warmingSettleId; // s.settleCount when `warming` was last added
        uint256 pendingUnstake; // non-earning, withdrawable after unlockAt
        uint64 unlockAt;
        uint256 rewardDebt;
        uint256 claimable; // settled, unclaimed rewards
    }

    struct BasketState {
        address curator;
        uint256 totalActive;
        uint256 totalWarming;
        uint64 settleCount;
        uint256 queuedBackers;
        uint256 queuedCurator;
        uint256 curatorClaimable;
        uint256 accWifPerStake; // scaled by 1e18
        uint256 navLast; // 18-dec USD per 1e18 shares
        uint256 benchLast; // 8-dec benchmark price
        uint64 lastSettledAt;
    }

    event FactorySet(address factory);
    event HarvesterSet(address harvester);
    event BasketRegistered(address indexed basket, address indexed curator, uint256 nav, uint256 benchPrice);
    /// @param warming true if the stake is warming (earns from the next settle), false if immediately active
    event Staked(address indexed basket, address indexed account, uint256 amount, bool warming);
    event UnstakeRequested(address indexed basket, address indexed account, uint256 amount, uint64 unlockAt);
    event Withdrawn(address indexed basket, address indexed account, uint256 amount);
    event RewardsQueued(address indexed basket, uint256 backers, uint256 curator);
    event EpochSettled(
        address indexed basket,
        uint64 settledAt,
        uint256 navLast,
        uint256 navNow,
        uint256 benchLast,
        uint256 benchNow,
        bool beat,
        uint256 releasedBackers,
        uint256 releasedCurator,
        uint256 burned
    );
    event RewardsClaimed(address indexed basket, address indexed account, address to, uint256 amount);
    event CuratorClaimed(address indexed basket, address indexed curator, address to, uint256 amount);

    error OnlyFactory();
    error OnlyHarvester();
    error AlreadySet();
    error UnknownBasket();
    error AlreadyRegistered();
    error ZeroAmount();
    error InsufficientActive();
    error StillLocked(uint64 unlockAt);
    error TooEarly(uint64 nextSettleAt);
    error NotCurator();

    function EPOCH_ANCHOR() external pure returns (uint64); // 1794016800 = Sat 2026-11-07 02:00 UTC
    function EPOCH_LENGTH() external pure returns (uint64); // 7 days
    function UNSTAKE_COOLDOWN() external pure returns (uint64); // 7 days
    function MAX_PRICE_AGE() external pure returns (uint256); // 4 days
    function DEAD() external pure returns (address);

    /// @notice One-time wiring by the owner.
    function setFactory(address factory) external;
    function setHarvester(address harvester) external;

    /// @notice Factory only. Snapshots navLast and benchLast and sets lastSettledAt = block.timestamp.
    function registerBasket(address basket, address curator) external;

    /// @notice Pulls `amount` $WIF from msg.sender and credits `account`'s active stake on `basket`.
    function stakeFor(address basket, address account, uint256 amount) external;
    function stake(address basket, uint256 amount) external;
    /// @notice Moves stake (warming first, then active) -> pendingUnstake and resets unlockAt = now + UNSTAKE_COOLDOWN
    ///         (adding to an existing pending amount restarts the timer). Reverts InsufficientActive if
    ///         amount > warming + active.
    function requestUnstake(address basket, uint256 amount) external;
    function withdraw(address basket) external returns (uint256 amount);

    /// @notice Harvester only. PULLS backers + curator $WIF from msg.sender via safeTransferFrom (the harvester must
    ///         approve exactly that amount first), then adds to the queues for the current epoch (review finding R-2:
    ///         the vault can never be under-funded by a buggy caller).
    function queueRewards(address basket, uint256 backers, uint256 curator) external;

    /// @notice Permissionless. See the contract-level dev notes.
    function settle(address basket) external;

    function claim(address basket, address to) external returns (uint256 amount);
    function claimCurator(address basket, address to) external returns (uint256 amount);

    function basketState(address basket) external view returns (BasketState memory);
    function position(address basket, address account) external view returns (Position memory);
    function pendingRewards(address basket, address account) external view returns (uint256);
    function curatorActive(address basket) external view returns (bool);
    function nextSettleAt(address basket) external view returns (uint64);
    /// @notice The current unit-based NAV, or 0 if any feed is invalid. Used by the app.
    function navOf(address basket) external view returns (uint256 nav, bool valid);
}

project/src/interfaces/IBasket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/// @notice What happens to cash dividends (ERC-8056 multiplier increases of at most MAX_DIVIDEND_STEP).
enum DividendMode {
    Reinvest, // default stock behaviour: value stays in the basket
    PayInWif // the dividend portion is skimmed, sold for $WIF by the harvester, and streamed to holders
}

/// @notice Initialisation payload. The factory builds it, and the clone receives it exactly once.
struct BasketInit {
    string name;
    string symbol;
    address curator;
    address[] tokens; // 2..8 entries, strictly ascending by address (the factory validates)
    uint256[] rawUnits; // raw token amount per 1e18 shares, each > 0
    DividendMode mode;
    address harvester; // IFeeHarvester
    address wif; // $WIF token (reward token for PayInWif)
}

/// @title IBasket
/// @notice Immutable, fixed-unit, in-kind basket of Stock Tokens (ADR-0001). It has no owner.
/// @dev MINT: deposit ceil(rawUnits_i * shares / 1e18) of each component. The receiver gets shares - fee, and the
///      harvester gets fee = shares * FEE_BPS / 10000 (ADR-0002).
///      REDEEM: fee shares go to the harvester. The net shares are burned and each component pays
///      floor(effBal_i * net / totalSupplyBefore). Each leg is attempted independently, and a failed leg becomes an IOU (ADR-0003).
///      The harvester is EXEMPT from fees on both mint and redeem.
///      Every mint/redeem calls sync() first.
///      effBal_i := IERC20(token_i).balanceOf(this) - totalOwed[token_i]
///      INVARIANT INV-1: effBal_i * 1e18 >= rawUnits_i * totalSupply() for every i, at all times.
interface IBasket is IERC20 {
    // ---------------------------------------------------------------- events
    event Initialized(address indexed curator, address[] tokens, uint256[] rawUnits, DividendMode mode);
    event Minted(
        address indexed caller,
        address indexed receiver,
        address indexed referrer,
        uint256 shares,
        uint256 feeShares,
        uint256[] amountsIn
    );
    event Redeemed(
        address indexed owner,
        address indexed receiver,
        uint256 shares,
        uint256 feeShares,
        uint256[] amountsOut
    );
    event IOURecorded(address indexed account, address indexed token, uint256 amount);
    event IOUClaimed(address indexed account, address indexed token, address to, uint256 amount);
    /// @param dividend true if this sync was treated as a cash dividend (PayInWif and 1 < new/old <= 1.03)
    event MultiplierSynced(
        address indexed token,
        uint256 oldMultiplier,
        uint256 newMultiplier,
        bool dividend,
        uint256 newRawUnits,
        uint256 skimmed
    );
    event WifDividendNotified(uint256 amount, uint256 accWifPerShare);
    event WifDividendClaimed(address indexed account, address indexed to, uint256 amount);

    // ---------------------------------------------------------------- errors
    error AlreadyInitialized();
    error OnlyHarvester();
    error ZeroShares();
    error BelowMinimumMint(uint256 shares, uint256 minimum);
    error ZeroAddress();
    error NothingOwed();
    error NotPayInWif();
    error NoSupply();

    // ---------------------------------------------------------------- constants
    /// @return 30 (0.30%) on mint and redeem.
    function FEE_BPS() external pure returns (uint256);
    /// @return 1000: the share of each fee attributed to the referrer (10% of the fee), if one is given.
    function REFERRAL_SHARE_BPS() external pure returns (uint256);
    /// @return 1.03e18: the largest multiplier step treated as a cash dividend (ADR-0006).
    function MAX_DIVIDEND_STEP() external pure returns (uint256);
    /// @return 1e12: the minimum shares per mint (dust guard).
    function MIN_MINT_SHARES() external pure returns (uint256);

    // ---------------------------------------------------------------- lifecycle
    /// @notice Called once by the factory immediately after cloning. It sets lastMultiplier_i = uiMultiplier() for each token.
    function initialize(BasketInit calldata init) external;

    // ---------------------------------------------------------------- core
    /// @notice Pulls components from msg.sender and mints shares.
    /// @param shares gross shares. The receiver gets shares - fee (or all of them if msg.sender is the harvester).
    /// @param referrer optional (address(0) = none). Forwarded to harvester.onFeeShares.
    /// @return sharesOut shares credited to the receiver
    /// @return amountsIn components pulled (ceil-rounded)
    function mint(
        uint256 shares,
        address receiver,
        address referrer
    ) external returns (uint256 sharesOut, uint256[] memory amountsIn);

    /// @notice Burns msg.sender's shares and sends the components to `receiver`. It never reverts because of one failed leg.
    /// @return amountsOut the amounts per component attributed to the receiver (paid now or recorded as an IOU)
    function redeem(uint256 shares, address receiver) external returns (uint256[] memory amountsOut);

    /// @notice Permissionless. Applies multiplier changes (section 5.3 of ARCHITECTURE.md). Idempotent.
    function sync() external;

    /// @notice Pays an IOU once the token transfers again. Reverts NothingOwed if the amount is 0.
    function claimIOU(address token, address to) external returns (uint256 amount);

    /// @notice Harvester only. The $WIF is already transferred in. accWifPerShare += amount * 1e18 / totalSupply().
    /// @dev Reverts NotPayInWif in Reinvest mode, and NoSupply if totalSupply() == 0.
    function notifyWifDividend(uint256 amount) external;

    function claimWifDividend(address to) external returns (uint256 amount);

    // ---------------------------------------------------------------- views
    function factory() external view returns (address);
    function curator() external view returns (address);
    function harvester() external view returns (address);
    function mode() external view returns (DividendMode);
    function components() external view returns (address[] memory tokens, uint256[] memory rawUnits);
    function lastMultipliers() external view returns (uint256[] memory);
    function effectiveBalances() external view returns (uint256[] memory);
    function owed(address account, address token) external view returns (uint256);
    function totalOwed(address token) external view returns (uint256);
    function pendingWifDividend(address account) external view returns (uint256);
    /// @notice Component amounts needed to mint `shares` at the CURRENT rawUnits (it does not simulate a pending sync).
    function previewMint(uint256 shares) external view returns (uint256[] memory amountsIn);
    /// @notice Component amounts `owner` would receive for redeeming `shares` (after the fee, unless owner is the harvester).
    function previewRedeem(uint256 shares, address owner) external view returns (uint256[] memory amountsOut);
}

project/src/interfaces/IBasketFactory.so.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {DividendMode} from "./IBasket.sol";

/// @title IBasketFactory
/// @notice Validates parameters, deploys Basket clones (EIP-1167, OZ Clones), registers them in the vault, and stakes
///         the curator's $WIF.
interface IBasketFactory {
    struct CreateParams {
        string name; // 1..32 bytes
        string symbol; // 1..11 bytes
        address[] tokens; // 2..8, strictly ascending by address, each registry.isEnabled
        uint256[] rawUnits; // same length, each > 0
        DividendMode mode;
    }

    event BasketCreated(
        address indexed basket,
        address indexed curator,
        string name,
        string symbol,
        address[] tokens,
        uint256[] rawUnits,
        DividendMode mode,
        uint256 curatorStake
    );
    event MinCuratorStakeSet(uint256 amount);
    event CreatePausedSet(bool paused);

    error CreatePaused();
    error BadLength();
    error TooFewComponents();
    error TooManyComponents();
    error NotAscending(); // also catches duplicates
    error ComponentDisabled(address token);
    error ZeroUnits(uint256 index);
    error BadName();
    error BadSymbol();
    error StakeTooLow(uint256 provided, uint256 minimum);

    /// @notice msg.sender becomes the curator. Pulls `curatorStake` $WIF from msg.sender (it needs an approval to the
    ///         factory) and stakes it in the vault for msg.sender via vault.stakeFor.
    /// @dev Order: clone -> basket.initialize -> vault.registerBasket (it snapshots NAV from basket.components(), so it
    ///      MUST come after initialize) -> pull stake -> vault.stakeFor.
    function createBasket(CreateParams calldata p, uint256 curatorStake) external returns (address basket);

    function isBasket(address account) external view returns (bool);
    function basketCount() external view returns (uint256);
    function basketAt(uint256 index) external view returns (address);

    function minCuratorStake() external view returns (uint256);
    function createPaused() external view returns (bool);
    /// @notice Owner only. Affects future baskets and the vault's curatorActive check.
    function setMinCuratorStake(uint256 amount) external;
    /// @notice Owner only. Pauses createBasket ONLY. It never affects existing baskets.
    function setCreatePaused(bool paused) external;

    function registry() external view returns (address);
    function harvester() external view returns (address);
    function vault() external view returns (address);
    function wif() external view returns (address);
    function implementation() external view returns (address);

    function MIN_COMPONENTS() external pure returns (uint256); // 2
    function MAX_COMPONENTS() external pure returns (uint256); // 8
}

project/src/interfaces/IComponentRegistr.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title IComponentRegistry
/// @notice The allowlist of Stock Tokens a basket may hold, with each token's price feed and Uniswap v3 USDG pool fee tier.
/// @dev Owner-managed with Ownable2Step. It has NO power over funds. Disabling a component blocks only NEW baskets
///      (factory) and router buys. Existing baskets keep working and redeem is unaffected.
interface IComponentRegistry {
    struct Component {
        bool enabled;
        address priceFeed; // Chainlink AggregatorV3, 8 decimals. Must be non-zero to enable.
        uint24 v3Fee; // fee tier of the token/USDG Uniswap v3 pool used for routing (100, 500, 3000 or 10000)
    }

    event ComponentSet(address indexed token, bool enabled, address priceFeed, uint24 v3Fee);
    event BenchmarkSet(address indexed token);

    error ZeroAddress();
    error InvalidFeeTier(uint24 fee);
    /// @dev Thrown by setComponent if enabling a token whose USDG pool does not exist at `v3Fee` on the configured factory.
    error PoolNotFound(address token, uint24 fee);
    error ComponentNotEnabled(address token);

    /// @notice Owner only. Enables or updates a component. To disable, pass enabled=false (feed and fee may be zero).
    /// @dev When enabling: priceFeed != 0, v3Fee is in {100,500,3000,10000}, and v3Factory.getPool(token, USDG, fee) != 0.
    function setComponent(address token, bool enabled, address priceFeed, uint24 v3Fee) external;

    /// @notice Owner only. The benchmark for Beat-SPY settlement. It must be an enabled component.
    function setBenchmark(address token) external;

    function component(address token) external view returns (Component memory);
    function isEnabled(address token) external view returns (bool);
    function benchmark() external view returns (address);
    function usdg() external view returns (address);
    function v3Factory() external view returns (address);
}
